<x-layouts.storefront :title="$receipt->payment_number.' · TGIF'">
    <section class="sf-receipt"><p class="sf-kicker">TGIF · {{ $receipt->kind === 'refund' ? 'REFUND ACKNOWLEDGMENT' : 'PAYMENT RECEIPT' }}</p><h1>{{ $receipt->kind === 'refund' ? 'Refund recorded.' : 'Thank you for your payment.' }}</h1><dl><div><dt>Receipt number</dt><dd>{{ $receipt->payment_number }}</dd></div><div><dt>Order</dt><dd>{{ $order->order_number }}</dd></div><div><dt>Date</dt><dd>{{ $receipt->payment_date }}</dd></div><div><dt>Method</dt><dd>{{ ucfirst(str_replace('_', ' ', $receipt->method)) }}</dd></div><div><dt>Amount</dt><dd class="sf-receipt-amount">{{ $receipt->currency }} {{ number_format($receipt->amount, 2) }}</dd></div></dl><button class="sf-button sf-print-button" onclick="window.print()">Print / save receipt ↗</button><a class="sf-text-link" href="{{ route(auth()->user()->role === 'admin' ? 'finance.payments' : 'customer.orders.show', auth()->user()->role === 'admin' ? ['order' => $order->order_id] : [$order->order_id]) }}">Back to order</a></section>
